// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address nonOwner = address(0x1);
        address target = address(0x2);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool sent,) = address(c).call{value: 1 ether}("");
        assertTrue(sent);

        uint targetBalanceBefore = target.balance;
        vm.prank(c.owner());
        c.sendMoney(target, 1 ether, "");
        uint targetBalanceAfter = target.balance;
        assertTrue(targetBalanceAfter > targetBalanceBefore);
    }
}
